// The parabola y = x^2 - 5x + 6, with both x-intercepts marked.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
import graph;
size(131,241);
pair O=(0,0);
real f(real x){return x*x-5*x+6;}
pair A=(-0.6,0), B=(6.6,0);
draw(A--B,Arrow);
label("$x$",B,SE);
draw((0,0)--(0,9.5),Arrow);
label("$y$",(0,9.5),N);
draw(graph(f,-0.6,6.6,400),blue);
dot((2,0), black+2.5pt);
dot((3,0), black+2.5pt);
label("$2$",(2,-1.1),S);
label("$3$",(3,-1.1),S);
dot((0,0), black+2.5pt);
label("$O$",(0,0),SW);
label("$y=x^{2}-5x+6$",(5.9,8.6),N);
